<?php

namespace App\Policies;

use App\Models\Invoice;
use App\Models\User;

/**
 * Invoices are generated by closing a billing period and are never edited by hand.
 */
class InvoicePolicy
{
    /**
     * Listing is scoped per panel: staff see every invoice, owners only their own.
     */
    public function viewAny(User $user): bool
    {
        return true;
    }

    public function view(User $user, Invoice $invoice): bool
    {
        return $user->role->canAccessBackOffice() || $user->ownsUnit($invoice->unit);
    }

    public function create(User $user): bool
    {
        return false;
    }

    public function update(User $user, Invoice $invoice): bool
    {
        return false;
    }

    public function delete(User $user, Invoice $invoice): bool
    {
        return false;
    }
}
